// https://emojibase.dev version 17.0.0

const b4a = require('b4a')
const { hostToLE16, hostToLE32 } = require('convert-endianness')

const INDEX = b4a.from('', 'base64')

exports.EMOJI_COUNT = 1949
exports.SKIN_COUNT = 475
exports.TAG_COUNT = 3638
exports.GROUP_COUNT = 10

exports.EMOJI_RECORDS = to32(0, 62368)
exports.SKIN_RECORDS = to32(62368, 71868)
exports.SHORTCODES = to32(71868, 84728)
exports.EMOTICONS = to32(84728, 84984)
exports.GROUPS = to32(84984, 85064)
exports.POINTS = to32(85064, 112312)
exports.TAG_STR_OFFSETS = to16(112312, 119590)
exports.POSTING_OFFSETS = to16(119590, 126868)
exports.POSTINGS = to16(126868, 147292)
exports.TAG_STRINGS = INDEX.subarray(147292, 168530)
exports.STRINGS = INDEX.subarray(168530, 292518)

function to16 (offset, end) {
  const arr = new Uint16Array(INDEX.buffer, offset, (end - offset) / 2)
  hostToLE16(arr)
  return arr
}

function to32 (offset, end) {
  const arr = new Uint32Array(INDEX.buffer, offset, (end - offset) / 4)
  hostToLE32(arr)
  return arr
}
